def moving_average(xs: list[float], n: int) -> list[float]:
    if n <= 0 or n > len(xs):
        raise ValueError("n must be in the range 1..len(xs)")
    return [
        sum(xs[i : i + n]) / n
        for i in range(len(xs) - n + 1)
    ]
